from django.http import JsonResponse

from catalog.models import Book

ALLOWED_FILTERS = {"title__icontains", "year", "author__name"}


def search(request):
    filters = {key: value for key, value in request.GET.items() if key in ALLOWED_FILTERS}
    books = Book.objects.filter(**filters)
    return JsonResponse({"titles": list(books.values_list("title", flat=True))})
